package edu.ankara.audiometer.domain.fp;
import java.util.*;import java.util.function.*;
public sealed interface Maybe<T> permits Maybe.Some, Maybe.None { boolean isPresent(); T orElse(T other); <U> Maybe<U> map(Function<T,U> f); Optional<T> toOptional(); static <T> Maybe<T> some(T v){return new Some<>(Objects.requireNonNull(v));} static <T> Maybe<T> none(){return new None<>();} record Some<T>(T value) implements Maybe<T>{ public boolean isPresent(){return true;} public T orElse(T other){return value;} public <U> Maybe<U> map(Function<T,U> f){return some(f.apply(value));} public Optional<T> toOptional(){return Optional.of(value);} } record None<T>() implements Maybe<T>{ public boolean isPresent(){return false;} public T orElse(T other){return other;} public <U> Maybe<U> map(Function<T,U> f){return none();} public Optional<T> toOptional(){return Optional.empty();} } }
